    text: `Belediye sınırları dışındaki her türlü işyerleri ile belediye sınırları içinde olmakla beraber, posta değişim saatlerinde toplu taşıma araçları ile gidip gelme zorluğu bulunan işyerlerinde, gece postalarında çalıştırılacak kadın çalışanların, sağlanacak uygun araçlarla, ikametgâhlarına en yakın merkezden, işyerine götürülüp getirilmemesi.`
