    text: `Çalışma ortamı, kullanılan maddeler, iş ekipmanı ile çevre şartlarının dikkate alınarak meydana gelebilecek ve çalışan ile çalışma çevresini etkileyecek acil durumların önceden değerlendirilerek muhtemel acil durumların belirlenmemesi.`
