    categoryId: 27,
    text: `Güvenli bir çalışma ortamı sağlamak amacıyla risk değerlendirmesinde yer alan fiziksel, kimyasal ve biyolojik tehlike kaynaklarının varlığının, niteliğinin ve niceliğinin ortam ve kişisel maruziyet ölçüm, test ve analiziyle tespit edilmemesi.`
