    categoryId: 6,
    text: `Alçak veya yüksek seviyede olan hareketli veya sabit çalışma yerlerinin, çalışan sayısı, üzerlerinde bulunabilecek azami ağırlık ve bu ağırlığın dağılımı ile maruz kalabileceği dış etkiler göz önünde bulundurularak yeterli sağlamlık ve dayanıklılıkta olmaması. Bu çalışma yerlerinin tamamının veya bir kısmının, zamansız veya kendiliğinden hareketini önlemek için uygun ve güvenilir sabitleme metotlarının kullanılmaması. Çalışma yerlerinin sağlamlığının ve dayanıklılığının özellikle de çalışma yerinin yükseklik veya derinliğinde değişiklik olduğunda kontrol edilmemesi.`
