    text: `Çalışanların biyolojik etkenlerle çalışmaya bağlı sağlık veya güvenlik riskleriyle karşılaştıkları bütün işlerde, çalışanlara, göz yıkama sıvıları ve/veya cilt antiseptikleri de dahil, uygun ve yeterli temizlik malzemeleri bulunan tuvalet imkanının sağlanmaması.`
