    text: `Çalışanların biyolojik etkenlerle çalışmaya bağlı sağlık veya güvenlik riskleriyle karşılaştıkları bütün işlerde, gerekli koruyucu donanım ve ekipmanın, belirlenmiş bir yerde uygun olarak muhafaza edilmemesi. Her kullanımdan sonra ve mümkünse kullanımdan önce kontrol edilip temizlenmemesi. Koruyucu donanım ve ekipmanın, kullanımından önce bozuksa tamir edilmemesi veya değiştirilmemesi.`
