    text: `EK-III’te bulunan tablolarda yer alan ekipman veya ekipman grupları periyodik kontrole tabi tutulmaması. İş ekipmanlarının periyodik kontrollerinin periyodik kontrolleri yapmaya yetkili kişiler tarafından yapılmaması. Periyodik kontrollerin gerçekleştirilmesine ilişkin şartlar ile periyodik kontrol sonucunda düzenlenecek belgelerle ilgili EK-III'te yer alan usul ve esaslara riayet edilmemesi. Ekipman grubunun kapsadığı ve ilgili tabloda standart karşılığı olmayan ekipmanların periyodik kontrollerinin EK-III’ün 1.1 inci ve 1.4 üncü maddelerinde yer alan hiyerarşiye göre yapılmaması.`
