    text: `Toplantının gündemi, yeri, günü ve saatinin toplantıdan en az kırk sekiz saat önce kurul üyelerine bildirilmemesi. Gündemin, sorunların ve varsa iş sağlığı ve güvenliğine ilişkin projelerin önem sırasına göre belirlenmemesi.`
