    text: `Birden fazla işyerinin bulunduğu iş merkezleri, iş hanları, sanayi bölgeleri veya siteleri gibi yerlerde, işyerlerinde ayrı ayrı gerçekleştirilen risk değerlendirmesi çalışmalarının koordinasyonunun yürütümünde, yönetimin, işyerlerinde iş sağlığı ve güvenliği yönünden diğer işyerlerini etkileyecek tehlikeler hususunda gerekli tedbirleri almaları için ilgili işverenleri uyarmaması ve bu uyarılara uymayan işverenleri Bakanlığa bildirmemesi.`
