    text: `Temel eğitimlerin tekrarında Ek-1’de yer alan dördüncü konu başlığının; 12 nci maddenin üçüncü fıkrasına uygun eğitim yöntemi kullanılarak 13 üncü maddenin üçüncü fıkrasında belirtilen sürelerde verilmesinin sağlanmaması.`
