    text: `Sınavlarda yüz puan üzerinden en az altmış puan alan katılımcıların başarılı sayılmaması. İlk sınavda başarısız olan katılımcıların en fazla iki defa daha ilgili sınavlara katılımının sağlanmaması. Bu sınavlarda başarısız olan katılımcıların temel eğitime yeniden katılımının sağlanmaması.`
